@startuml

class Doctor {
  + practitionerNumber : int
  + signature : string
  + fullName : string
  + address : string
  + phoneNumber : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
}

class Test {
  + duration : int
}

class TestGroup {
  + name : string
}

class RepetitionPattern {
  + interval : string
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class Lab {
  + address : string
  + registrationNumber : string
  + businessHoursStart : time
  + businessHoursEnd : time
  + cancellationFee : float
}

class TestResult {
  + isPositive : boolean
  + report : string
}

class TestItem {
  + repetitionCount : int
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" *-- "1..*" TestItem
TestItem "*" -- "1" Test : refers to
Test "0..*" -- "1" TestGroup
Test "1" -- "0..1" RepetitionPattern : follows
Requisition "1" -- "0..1" RepetitionPattern : follows
Appointment "1" -- "1" Requisition : for
Appointment "1" -- "1" Lab : at
Patient "1" -- "*" Appointment : books
Test "1" -- "0..*" TestResult : produces
Test "1" -- "0..*" TestResult : produces
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views

@enduml

